package com.github.ydewolf.ysoulmana.content.mana;import com.github.ydewolf.ysoulmana.api.entity.EntityManaPool;public class PlayerMana extends EntityManaPool implements IPlayerMana {    private float totalManaUsed = 0.0f;    @Override    public float getTotalManaUsed() {        return this.totalManaUsed;    }    @Override    public void setTotalManaUsed(float mana) {        this.totalManaUsed = mana;    }    @Override    public void addTotalManaUsed(float amount) {        this.totalManaUsed += amount;    }    public boolean consumeMana(float amount) {        if (this.canConsumeMana(amount)) {            this.addTotalManaUsed(amount);            this.setMana(this.mana - amount);            return true;        }        return false;    }    @Override    public void copyFrom(IPlayerMana source) {        this.totalManaUsed = source.getTotalManaUsed();        super.copyFrom(source);    }}